export function TabNav(t,a){return`\n        <div class="battles-tab-nav" role="tablist" aria-label="Battles Sections">\n            <div class="battles-tab-scroll">\n                ${t.map(t=>{const l=t.id===a;return`<button class="battles-tab-btn ${l?"active":""}" data-tab="${t.id}" aria-selected="${l}" role="tab">${t.label}</button>`}).join("")}\n            </div>\n        </div>\n    `}